package dev.veltraph.client.inventory.bottle;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class BottleFillWorkflowTest {
    static final BottleFillWorkflow.Identity GLASS=new BottleFillWorkflow.Identity("minecraft:glass_bottle","Glass Bottle","[glass]"),WATER=new BottleFillWorkflow.Identity("minecraft:potion","Water Bottle","[water]");
    static BottleFillWorkflow.Request request(int quantity){return new BottleFillWorkflow.Request(GLASS,WATER,quantity,"minecraft:overworld",new BottleFillWorkflow.Position(4,70,0),new BottleFillWorkflow.Position(2,70,0),new BottleFillWorkflow.Position(-2,70,0),new BottleFillWorkflow.Position(-1,70,0),"Chest",1,30);}
    static class Port implements BottleFillWorkflow.Port {
        Object player=new Object(),world=new Object(),menu;String title="";int revision=1,selected=2,uses,stores,opens,swaps,closes;boolean cursor=true,source=true,chestValid=true,fill=true,acceptStore=true,predictStore=true,refuse,correct=true;
        List<BottleFillWorkflow.Stack> inventory=new ArrayList<>(Collections.nCopies(36,BottleFillWorkflow.Stack.EMPTY)),chest=new ArrayList<>(Collections.nCopies(27,BottleFillWorkflow.Stack.EMPTY)),serverInventory;
        Port(){inventory.set(2,new BottleFillWorkflow.Stack(new BottleFillWorkflow.Identity("minecraft:diamond_sword","Tool","[tool]"),1,true));inventory.set(17,new BottleFillWorkflow.Stack(GLASS,3,false));}
        public BottleFillWorkflow.Observation read(BottleFillWorkflow.Request r){var rows=new ArrayList<BottleFillWorkflow.Row>();if(menu!=null){for(int i=0;i<27;i++)rows.add(new BottleFillWorkflow.Row(i,-1,chest.get(i)));for(int i=0;i<36;i++)rows.add(new BottleFillWorkflow.Row(27+i,i,inventory.get(i)));}
            return new BottleFillWorkflow.Observation(player,world,menu,title,revision,"minecraft:overworld",inventory,rows,selected,cursor,correct,source,chestValid);}
        public boolean swap(BottleFillWorkflow.Observation o,int main,int hotbar){if(refuse)return false;swaps++;Collections.swap(inventory,main,hotbar);return true;}
        public boolean select(BottleFillWorkflow.Observation o,int slot){if(refuse)return false;selected=slot;return true;}
        public BottleFillWorkflow.Approach approach(BottleFillWorkflow.Observation o,BottleFillWorkflow.Position target,BottleFillWorkflow.Position stand){return refuse?BottleFillWorkflow.Approach.BLOCKED:BottleFillWorkflow.Approach.READY;}
        public boolean fill(BottleFillWorkflow.Observation o,BottleFillWorkflow.Position source){uses++;if(fill){var s=inventory.get(selected);if(s.count()==1)inventory.set(selected,new BottleFillWorkflow.Stack(WATER,1,false));else{inventory.set(selected,s.withCount(s.count()-1));int out=0;while(!inventory.get(out).empty())out++;inventory.set(out,new BottleFillWorkflow.Stack(WATER,1,false));}}return true;}
        public boolean open(BottleFillWorkflow.Observation o,BottleFillWorkflow.Position target){if(refuse)return false;opens++;menu=new Object();title="Chest";if(serverInventory!=null){inventory=new ArrayList<>(serverInventory);serverInventory=null;}return true;}
        public boolean store(BottleFillWorkflow.Observation o,int index){if(refuse)return false;stores++;if(!acceptStore)serverInventory=List.copyOf(inventory);if(acceptStore){int out=0;while(!chest.get(out).empty())out++;chest.set(out,inventory.get(index));}if(acceptStore||predictStore)inventory.set(index,BottleFillWorkflow.Stack.EMPTY);return true;}
        public boolean close(BottleFillWorkflow.Observation o){if(refuse)return false;closes++;menu=null;title="";return true;}
        public void release(){}
    }
    private static void drive(BottleFillWorkflow w,int n){for(int i=1;i<=n&&w.active();i++)w.tick(i);}
    private static void reach(BottleFillWorkflow w,BottleFillWorkflow.State state){for(int i=1;i<80&&w.active()&&w.state()!=state;i++)w.tick(i);assertEquals(state,w.state(),w.reason());}
    @Test void repeatedNativeContractStoresAndRestoresPartialStack(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);drive(w,100);assertEquals(BottleFillWorkflow.State.COMPLETE,w.state(),w.reason());assertEquals(2,w.completed());assertEquals(2,p.uses);assertEquals(2,p.stores);assertEquals(5,p.opens);assertEquals(2,p.swaps);assertEquals(1,p.inventory.get(17).count());assertEquals(GLASS,p.inventory.get(17).identity());assertTrue(p.inventory.get(0).empty());assertEquals(2,p.selected);assertNull(p.menu);assertEquals(2,p.chest.stream().filter(WATER::matches).count());}
    @Test void singleLastGlassConvertsInHandAndHotbarStackNeedsNoTransfer(){var p=new Port();p.inventory.set(5,new BottleFillWorkflow.Stack(GLASS,1,false));p.inventory.set(17,BottleFillWorkflow.Stack.EMPTY);var w=new BottleFillWorkflow(p);w.start(request(1),0);drive(w,100);assertEquals(BottleFillWorkflow.State.COMPLETE,w.state(),w.reason());assertEquals(0,p.swaps);assertTrue(p.inventory.get(5).empty());assertEquals(1,w.completed());assertEquals(2,p.selected);}
    @Test void missingWaterAndMissingGlassNeverAct(){for(boolean water:new boolean[]{false,true}){var p=new Port();p.source=water;if(water)p.inventory.set(17,BottleFillWorkflow.Stack.EMPTY);var w=new BottleFillWorkflow(p);w.start(request(2),0);assertEquals(BottleFillWorkflow.State.FAILED,w.state());assertEquals(0,p.uses);assertEquals(0,p.swaps);}}
    @Test void toolAndOccupiedHotbarNeverDisplaced(){for(boolean tool:new boolean[]{false,true}){var p=new Port();if(tool)p.inventory.set(17,new BottleFillWorkflow.Stack(GLASS,3,true));else for(int i=0;i<9;i++)p.inventory.set(i,p.inventory.get(2));var before=List.copyOf(p.inventory);var w=new BottleFillWorkflow(p);w.start(request(2),0);assertEquals(BottleFillWorkflow.State.FAILED,w.state());assertEquals(before,p.inventory);assertEquals(0,p.swaps);}}
    @Test void noFillAcknowledgmentDoesNotRetry(){var p=new Port();p.fill=false;var w=new BottleFillWorkflow(p);w.start(request(2),0);drive(w,100);assertEquals(BottleFillWorkflow.State.FAILED,w.state(),w.reason());assertEquals(1,p.uses);assertEquals(0,p.stores);assertEquals(3,p.inventory.get(17).count());}
    @Test void predictedStorageNeedsFreshServerContents(){var p=new Port();p.acceptStore=false;var w=new BottleFillWorkflow(p);w.start(request(2),0);drive(w,100);assertEquals(BottleFillWorkflow.State.FAILED,w.state(),w.reason());assertEquals(0,w.completed());assertEquals(1,p.uses);assertEquals(1,p.stores);assertEquals(0,p.chest.stream().filter(WATER::matches).count());assertEquals(1,p.inventory.stream().filter(WATER::matches).count());}
    @Test void wrongOutputMetadataCannotBeAccepted(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.WAIT_FILL);for(int i=0;i<36;i++)if(WATER.matches(p.inventory.get(i)))p.inventory.set(i,new BottleFillWorkflow.Stack(new BottleFillWorkflow.Identity("minecraft:potion","Water Bottle","[wrong]"),1,false));w.tick(10);assertEquals(BottleFillWorkflow.State.RECOVERY_REQUIRED,w.state());assertEquals(0,p.stores);}
    @Test void cancellationDrainsFillWithoutStoringOrUsingAgain(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.WAIT_FILL);w.cancel();drive(w,100);assertEquals(BottleFillWorkflow.State.CANCELLED,w.state(),w.reason());assertEquals(1,p.uses);assertEquals(0,p.stores);assertEquals(2,p.inventory.get(17).count());assertEquals(1,p.inventory.stream().filter(WATER::matches).count());}
    @Test void cancellationAfterStoreVerifiesItsResultButNeverFillsAgain(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.WAIT_STORE);w.cancel();drive(w,100);assertEquals(BottleFillWorkflow.State.CANCELLED,w.state(),w.reason());assertEquals(1,p.uses);assertEquals(1,p.stores);assertEquals(1,w.completed());assertEquals(2,p.inventory.get(17).count());}
    @Test void foreignMenuSameTitleAfterBindingPreserved(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.STORE);Object replacement=new Object();p.menu=replacement;drive(w,100);assertEquals(BottleFillWorkflow.State.RECOVERY_REQUIRED,w.state());assertSame(replacement,p.menu);assertEquals(0,p.stores);assertEquals(0,p.closes);}
    @Test void worldCursorAndOtherInventoryDeltaStopWithoutOverwrite(){for(int kind=0;kind<3;kind++){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.WAIT_FILL);if(kind==0)p.world=new Object();if(kind==1)p.cursor=false;if(kind==2)p.inventory.set(17,new BottleFillWorkflow.Stack(new BottleFillWorkflow.Identity("minecraft:diamond","Foreign","[foreign]"),1,false));w.tick(10);assertEquals(BottleFillWorkflow.State.RECOVERY_REQUIRED,w.state());assertEquals(1,p.swaps);assertEquals(0,p.stores);}}
    @Test void parentBoundStackChunksPreserveOtherAcquired64Stacks(){var p=new Port();p.inventory.set(17,new BottleFillWorkflow.Stack(GLASS,37,false));p.inventory.set(18,new BottleFillWorkflow.Stack(GLASS,64,false));var w=new BottleFillWorkflow(p);w.start(request(2),0,17);drive(w,100);assertEquals(BottleFillWorkflow.State.COMPLETE,w.state(),w.reason());assertEquals(35,p.inventory.get(17).count());assertEquals(64,p.inventory.get(18).count());assertEquals(2,w.completed());assertEquals(2,p.selected);assertTrue(p.inventory.get(2).tool());}
    @Test void standaloneStillRefusesMultiplePreparedStacks(){var p=new Port();p.inventory.set(18,new BottleFillWorkflow.Stack(GLASS,64,false));var w=new BottleFillWorkflow(p);w.start(request(2),0);assertEquals(BottleFillWorkflow.State.FAILED,w.state());assertEquals(0,p.uses);}
    @Test void parentBindingCannotSelectProtectedOrInsufficientStack(){for(int index:new int[]{2,18,36}){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(4),0,index);assertEquals(BottleFillWorkflow.State.FAILED,w.state());assertEquals(0,p.swaps);assertEquals(0,p.uses);}}
    @Test void xpIdentityAndUnboundedRequestsRefused(){assertThrows(IllegalArgumentException.class,()->new BottleFillWorkflow.Request(GLASS,new BottleFillWorkflow.Identity("minecraft:experience_bottle","Bottle","[]"),2,"dimension",request(2).source(),request(2).sourceStand(),request(2).chest(),request(2).chestStand(),"Chest",1,30));assertThrows(IllegalArgumentException.class,()->request(65));assertThrows(IllegalArgumentException.class,()->dev.veltraph.client.config.BottleFillConfig.request(new dev.veltraph.client.config.MapConfigService()));}
    @Test void explicitManualRecoveryVerifiesKnownPairWithoutAnyNativeAction(){var p=new Port();var w=new BottleFillWorkflow(p);w.start(request(2),0);reach(w,BottleFillWorkflow.State.WATER);p.world=new Object();w.tick(10);assertEquals(BottleFillWorkflow.State.RECOVERY_REQUIRED,w.state());assertFalse(w.recoveryReservesCurrentContext());assertFalse(w.acknowledgeManualRecovery());Collections.swap(p.inventory,17,0);p.inventory.set(20,new BottleFillWorkflow.Stack(new BottleFillWorkflow.Identity("minecraft:diamond","Manual item","[manual]"),2,false));assertTrue(w.acknowledgeManualRecovery());assertEquals(BottleFillWorkflow.State.FAILED,w.state());assertEquals(0,w.completed());assertEquals(1,p.swaps);assertEquals(0,p.uses);assertEquals(0,p.stores);}
}
